-- Two additional services, inserted INACTIVE with no fee. The owner sets and approves
-- a fee, then activates each in Admin → Services & pricing.
insert into public.services (slug,title,summary,description,scope,inclusions,exclusions,duration_minutes,fee_pkr,fee_is_starting_price,fee_needs_review,is_active,refund_terms,sort_order) values
('application-documents-review','CV, SOP & Application Review','Feedback on your CV, statement of purpose or personal statement before you apply.','You write your own CV and statements; we read them closely and give clear written feedback on structure, clarity and what to strengthen, so your application reads well. We do not write them for you.','Review and written feedback on documents prepared by you. Fee to be confirmed before this service opens.',array['Review of your CV and/or SOP or personal statement','Written feedback on structure, clarity and gaps','One round of follow-up questions'],array['Writing the documents on your behalf','Submitting any application','Any guarantee of admission, scholarship or visa outcome'],null,0,false,true,false,'Refund and cancellation conditions are set out in the Refund and Cancellation Policy (draft — pending owner approval).',4),
('business-setup-consultation','Business Setup Consultation','An introductory consultation on company-formation options and the documents involved.','A paid, clearly scoped conversation about the general options and documents for setting up a business. This is general information only; legal, tax and regulated advice is given by the relevant authorised professionals.','General orientation only. Fee and partners to be confirmed before this service opens.',array['Overview of common business-structure options','Indicative list of documents usually required','Suggested next steps and official links'],array['Legal, tax or accounting advice','Company registration or filing on your behalf','Government or regulator fees','Any guarantee of approval or business outcome'],30,0,false,true,false,'Refund and cancellation conditions are set out in the Refund and Cancellation Policy (draft — pending owner approval).',5)
on conflict (slug) do nothing;
